Here is a complete, production-ready example of a React `onSubmit` function that sends form data to a GraphQL API.

This example uses **React Hook Form** (the industry standard for complex forms) and **Apollo Client** (the standard for GraphQL state management).

### The `onSubmit` Function

```javascript
import { useMutation } from '@apollo/client';
import { gql } from '@apollo/client';

// 1. Define the GraphQL Mutation
const CREATE_USER_MUTATION = gql`
  mutation CreateUser($input: CreateUserInput!) {
    createUser(input: $input) {
      id
      email
      name
    }
  }
`;

export const useCreateUser = () => {
  // 2. Initialize the mutation hook
  const [createUser, { loading, error, data }] = useMutation(CREATE_USER_MUTATION, {
    // Optional: Handle errors globally or per-mutation
    onError: (err) => {
      console.error('GraphQL Error:', err);
      // You might want to trigger a toast notification here
    },
  });

  // 3. The onSubmit function
  const handleSubmit = async (formData) => {
    try {
      // A. Validate data (Optional but recommended)
      // If using React Hook Form, validation is usually handled by the schema
      if (!formData.email || !formData.name) {
        throw new Error('Please fill in all required fields');
      }

      // B. Prepare variables for the mutation
      // Map your form keys to the GraphQL input names
      const variables = {
        input: {
          email: formData.email,
          name: formData.name,
          // Add other fields here
        },
      };

      // C. Execute the mutation
      const result = await createUser(variables);

      // D. Handle success
      console.log('User created:', result.data.createUser);

      // Reset form or redirect
      // window.location.href = '/dashboard';

      return result;
    } catch (err) {
      // Handle client-side errors
      console.error('Submission failed:', err);
      throw err;
    }
  };

  return { handleSubmit, loading, error, data };
};
```

