```swift
import Foundation

// MARK: - Core AST Nodes

/// Represents a type in the Metal AST.
enum MetalType: Equatable {
    case void
    case float
    case int
    case sampler
    case texture2d
    case texture2d_array
    case textureCube
    case textureCubeArray
    case vector(size: Int, element: MetalType)
    case matrix(rows: Int, cols: Int, element: MetalType)
    case pointer(to: MetalType)
    case function(name: String, params: [MetalType], return: MetalType)
}

/// Represents a variable declaration.
struct VariableDecl {
    let name: String
    let type: MetalType
    let initializer: Expression?
}

/// Represents a function declaration.
struct FunctionDecl {
    let name: String
    let params: [VariableDecl]
    let return: MetalType
    let body: Statement
}

/// Represents a statement in the AST.
enum Statement {
    case empty
    case expression(Expression)
    case ifStatement(condition: Expression, then: Statement, else: Statement)
