### 1. The Worker (`app/workers/csv-worker.js`)

This file contains the heavy lifting. It reads the CSV string and converts it into an array of objects.

```javascript
// app/workers/csv-worker.js
export default class CsvWorker {
  constructor() {
    this.port = new MessageChannel().port1;
    this.port.onmessage = (event) => {
      const { type, payload } = event.data;
      if (type === 'parse') {
        const result = this.parseCSV(payload);
        this.port.postMessage({ type: 'result', payload: result });
      }
    };
  }

  parseCSV(csvString) {
    const lines = csvString.split(/\r\n|\n/);
    const headers = lines[0].split(',').map(h => h.trim());
    const data = [];

    for (let i = 1; i < lines.length; i++) {
      const values = lines[i].split(',').map(v => v.trim());
      const row = {};
      headers.forEach((header, index) => {
        row[header] = values[index] || '';
      });
      data.push(row);
    }

    return data;
  }

  sendParseRequest(csvString) {
    this.port.postMessage({ type: 'parse', payload: csvString });
  }
}
```

